import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 10 Silicon Valley","description":"学习 比较结构与范围限定，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 10 Silicon Valley","description":"学习 比较结构与范围限定，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 比较结构与范围限定，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 9 Royal espionage","link":"/life/english/new-concept/book-4/unit-02/lesson-009"},"next":{"text":"第四册：流利英语 · Lesson 11 How to grow old","link":"/life/english/new-concept/book-4/unit-02/lesson-011"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 9 Royal espionage","link":"/life/english/new-concept/book-4/unit-02/lesson-009"},"next":{"text":"第四册：流利英语 · Lesson 11 How to grow old","link":"/life/english/new-concept/book-4/unit-02/lesson-011"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-02/lesson-010.md","filePath":"life/english/new-concept/book-4/unit-02/lesson-010.md"}'),i={name:"life/english/new-concept/book-4/unit-02/lesson-010.md"};function l(r,e,s,h,c,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-10-silicon-valley" tabindex="-1">第四册：流利英语 · Lesson 10 Silicon Valley <a class="header-anchor" href="#第四册-流利英语-·-lesson-10-silicon-valley" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 10 Silicon Valley&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>借科技产业聚集讨论地点、人才与合作网络之间的关系，区分历史时期的产业描写和对今天的判断。学习把企业之间的相似点与差异点说清楚，避免把成功全部归于单一因素。输出一段比较两个虚构创新园区的说明，用比较基准支撑判断。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>cluster</td><td>/ˈklʌstə/</td><td>n.</td><td>集群</td><td>a technology cluster</td></tr><tr><td>venture</td><td>/ˈventʃə/</td><td>n.</td><td>创业项目</td><td>a new venture</td></tr><tr><td>innovation</td><td>/ˌɪnəˈveɪʃən/</td><td>n.</td><td>创新</td><td>encourage innovation</td></tr><tr><td>network</td><td>/ˈnetwɜːk/</td><td>n.</td><td>网络</td><td>a professional network</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>set up — 建立公司或机构</li><li>draw on — 利用已有经验或资源</li></ul><h2 id="语法讲解-比较结构与范围限定" tabindex="-1">语法讲解：比较结构与范围限定 <a class="header-anchor" href="#语法讲解-比较结构与范围限定" aria-label="Permalink to &quot;语法讲解：比较结构与范围限定&quot;">​</a></h2><p>more…than… 比较同一维度，as…as… 表示该维度相当。比较对象应对等，例如 the costs in Park A 与 those in Park B，而不是把成本与园区本身比较。the more…the more… 表示两个程度随之变化，但句型本身并不能证明因果。写产业说明时还要限定样本、时期和指标，不能从 more patents 直接推出 better companies。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Office rents in the new district are lower than those in the city centre.</p></blockquote><p>新区的办公室租金低于市中心的租金。</p><p>those 代替复数 office rents，保持比较对象一致；lower 是比较级表语。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>rents are lower than the city centre 把租金与地点比较，应补 those in。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 lower than those 时保留 those；把两处 Park 的名称读清楚，录音后让听者复述哪个租金更低。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Rents in River Park are lower than those in Hill Park. Hill Park offers more networking events. A small team may prefer River Park if keeping costs down is its priority.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>比较两个虚构办公园区：租金、人才交流、适用团队各写一句。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>每句使用具体维度，最后用 if 明确选择依赖的条件。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例中 those 代替什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> office rents</p><p><strong>解析：</strong> 复数代词避免重复比较对象。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：This laboratory is as large ___ the one next door.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> as</p><p><strong>解析：</strong> 同级比较采用 as…as…。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>仅凭一个园区专利更多，能推出其所有企业都更成功吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不能。</p><p><strong>解析：</strong> 专利数量只是一个指标，且园区总体不等于每家企业。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：比较结构与范围限定。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-009">上一课</a> · <a href="/life/english/new-concept/book-4/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-02/lesson-011">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(i,[["render",l]]);export{u as __pageData,k as default};
